69.       @Override
70.       public DataFetcher<?> visit(KafkaMutationCoords coords, Context context) {
71.         KafkaProducer<String, String> producer = KafkaProducer.create(vertx, getSinkConfig());
72.         SinkProducer emitter = new KafkaSinkProducer<>(coords.getTopic(), producer);
73.         final List<String> uuidColumns =
74.             coords.getComputedColumns().entrySet().stream()
75.                 .filter(e -> e.getValue() == MutationComputedColumnType.UUID)
76.                 .map(Map.Entry::getKey)
77.                 .collect(Collectors.toList());
78.         final List<String> timestampColumns =
79.             coords.getComputedColumns().entrySet().stream()
80.                 .filter(e -> e.getValue() == MutationComputedColumnType.TIMESTAMP)
81.                 .map(Map.Entry::getKey)
82.                 .collect(Collectors.toList());
83. 
84.         Preconditions.checkNotNull(
85.             emitter, "Could not find sink for field: %s", coords.getFieldName());
86.         return VertxDataFetcher.create(
87.             (env, fut) -> {
88.               var entry = getEntry(env, uuidColumns);
89. 
90.               emitter
91.                   .send(entry)
92.                   .onSuccess(
93.                       sinkResult -> {
94.                         // Add timestamp from sink to result
95.                         var dateTime =
96.                             ZonedDateTime.ofInstant(sinkResult.getSourceTime(), ZoneOffset.UTC);
97.                         timestampColumns.forEach(
98.                             colName -> entry.put(colName, dateTime.toOffsetDateTime()));
99. 
100.                         fut.complete(entry);
101.                       })
102.                   .onFailure((m) -> fut.fail(m));
103.             });
104.       }
