107.       public DataFetcher<?> visit(PostgresLogMutationCoords coords, Context context) {
108.         return VertxDataFetcher.create(
109.             (env, fut) -> {
110.               var entry = getEntry(env, List.of());
111.               entry.put(
112.                   "event_time", Timestamp.from(Instant.now())); // TODO: better to do it in the db
113. 
114.               var paramObj = new Object[coords.getParameters().size()];
115.               for (var i = 0; i < coords.getParameters().size(); i++) {
116.                 var param = coords.getParameters().get(i);
117.                 var o = entry.get(param);
118.                 if (o instanceof UUID iD) {
119.                   o = iD.toString();
120.                 } else if (o instanceof Timestamp timestamp) {
121.                   o = timestamp.toLocalDateTime().atOffset(ZoneOffset.UTC);
122.                 }
123.                 paramObj[i] = o;
124.               }
125. 
126.               var insertStatement = coords.getInsertStatement();
127. 
128.               var preparedQuery =
129.                   ((VertxJdbcClient) context.getClient())
130.                       .getClients()
131.                       .get("postgres")
132.                       .preparedQuery(insertStatement);
133.               preparedQuery
134.                   .execute(Tuple.from(paramObj))
135.                   .onComplete(e -> fut.complete(entry))
136.                   .onFailure(
