149.     // - input argument cannot be null.
150.     var args = env.getArguments();
151. 
152.     var entry = (Map) args.entrySet().stream().findFirst().map(Entry::getValue).get();
153. 
154.     if (!uuidColumns.isEmpty()) {
155.       // Add UUID for event for the computed uuid columns
156.       var uuid = UUID.randomUUID();
157.       uuidColumns.forEach(colName -> entry.put(colName, uuid));
158.     }
159.     return entry;
