+package com.datasqrl.graphql;
+
+import graphql.schema.DataFetcher;
+import graphql.schema.DataFetchingEnvironment;
+import io.vertx.core.Promise;
+
+final class VertxDataFetcher {
+
+  private VertxDataFetcher() {}
+
+  @FunctionalInterface
+  interface FetcherHandler {
+    void handle(DataFetchingEnvironment environment, Promise<Object> promise) throws Exception;
+  }
+
+  static DataFetcher<Object> create(FetcherHandler handler) {
+    return environment -> {
+      Promise<Object> promise = Promise.promise();
+      try {
+        handler.handle(environment, promise);
+      } catch (Throwable t) {
+        promise.fail(t);
+      }
+      return promise.future().toCompletionStage();
+    };
+  }
+}
